command:
$ErrorActionPreference = 'Stop'
$targetSha = '695cd1d0c2d16a3a2f9142b474dc6cb9f0285212'
function Invoke-Checked([string]$Label, [scriptblock]$Action) {
  Write-Host "=== $Label ==="
  & $Action
  if ($LASTEXITCODE -ne 0) { throw "$Label failed with exit $LASTEXITCODE" }
}
Write-Host "Validating exact PR head $targetSha"
git fetch --no-tags origin $targetSha
if ($LASTEXITCODE -ne 0) { throw 'Unable to fetch exact PR head' }
git checkout --detach $targetSha
if ($LASTEXITCODE -ne 0) { throw 'Unable to detach at PR head' }
$actual = (git rev-parse HEAD).Trim()
if ($actual -ne $targetSha) { throw "Detached checkout mismatch: expected $targetSha got $actual" }
Invoke-Checked 'Shared source contract' { python project_sources/agent_runtime/tools/validate_shared_agent_source_contract.py }
Invoke-Checked 'Shared source contract self-tests' { python project_sources/agent_runtime/tests/validate_shared_agent_source_contract_selftest.py }
Invoke-Checked 'Behavior adapter materialization check' { python project_sources/agent_runtime/tools/materialize_agent_behavior_adapters.py --check }
Invoke-Checked 'Behavior adapter self-tests' { python project_sources/agent_runtime/tests/materialize_agent_behavior_adapters_selftest.py }
Invoke-Checked 'Knowledge projection check' { python project_sources/agent_runtime/tools/project_agent_knowledge.py --check }
Invoke-Checked 'Knowledge projection self-tests' { python project_sources/agent_runtime/tests/project_agent_knowledge_selftest.py }
Invoke-Checked 'OpenAI DCOIR package check' { python project_sources/agent_runtime/tools/build_openai_dcoir_analyst.py --check }
Invoke-Checked 'OpenAI DCOIR package self-tests' { python project_sources/agent_runtime/tests/build_openai_dcoir_analyst_selftest.py }
Invoke-Checked 'OpenAI USB package check' { python project_sources/agent_runtime/tools/build_openai_usb_reporting.py --check }
Invoke-Checked 'OpenAI USB package self-tests plus unified release parity' { python project_sources/agent_runtime/tests/build_openai_usb_reporting_selftest.py }
$tracked = git status --porcelain --untracked-files=no
if ($LASTEXITCODE -ne 0) { throw 'Unable to inspect tracked working-tree state' }
if ($tracked) { $tracked | Out-Host; throw 'Validation changed tracked repository files' }
Write-Host 'Exact-head validation completed successfully.'
Write-Host "validated_head_sha=$targetSha"
git fetch --no-tags origin main
if ($LASTEXITCODE -ne 0) { throw 'Unable to refresh origin/main before returning runner' }
git checkout -B main origin/main
if ($LASTEXITCODE -ne 0) { throw 'Unable to return runner to main' }
Write-Host 'Runner returned to main for workflow report finalization.'
